import { useSyncExternalStore } from "react";

const MOBILE_BREAKPOINT = 768;

// module-scoped because useSyncExternalStore re-subscribes on identity change — per-call closure would rebuild listener every render
const viewportStores = new Map<number, { subscribe: (onChange: () => void) => () => void; getSnapshot: () => boolean }>();

function viewportStore(breakpoint: number) {
  const cached = viewportStores.get(breakpoint);
  if (cached) return cached;

  const mobileQuery = `(max-width: ${breakpoint - 1}px)`;
  const store = {
    subscribe(onChange: () => void) {
      const query = window.matchMedia(mobileQuery);
      query.addEventListener("change", onChange);
      return () => query.removeEventListener("change", onChange);
    },
    getSnapshot: () => window.matchMedia(mobileQuery).matches,
  };
  viewportStores.set(breakpoint, store);
  return store;
}

function getServerViewportSnapshot() {
  return false;
}

/** True below `breakpoint` px (Tailwind `md` by default); pass another breakpoint to match layout that switches elsewhere. */
export function useIsMobile(breakpoint: number = MOBILE_BREAKPOINT) {
  const store = viewportStore(breakpoint);
  return useSyncExternalStore(store.subscribe, store.getSnapshot, getServerViewportSnapshot);
}

@layer components {
  :where([data-control-family="sidebar"][data-slot="group-label"]) {
    gap: calc(var(--spacing) * 2);
    padding-inline: calc(var(--spacing) * 2);
    border-radius: var(--radius-md);
    color: var(--cui-sidebar-group-label-foreground);
    font-size: var(--text-caption);
    font-weight: var(--font-weight-medium);
    outline: none;
    transition-property: margin, opacity;
    transition-duration: var(--duration-base);
    transition-timing-function: var(--ease-standard);
  }

  :where([data-control-family="sidebar"][data-slot="menu-button"]),
  :where([data-control-family="sidebar"][data-slot="menu-action"]) {
    gap: calc(var(--spacing) * 1.5);
    block-size: var(--control-h-md);
    border-radius: var(--cui-sidebar-menu-button-radius);
    padding-inline: var(--padding-x);
    font-size: var(--text-body);
    background-color: transparent;
    color: var(--cui-sidebar-menu-button-foreground);
    outline: none;
    transition-property: width, height, padding, color, background-color, box-shadow;
    transition-duration: var(--duration-base);
    transition-timing-function: var(--ease-standard);
  }

  :where([data-control-family="sidebar"][data-slot="menu-button"][data-size="sm"]) {
    block-size: var(--control-h-sm);
    padding-inline: calc(var(--padding-x) * 0.75);
    font-size: var(--text-label);
  }

  :where([data-control-family="sidebar"][data-slot="menu-button"][data-size="lg"]) {
    gap: calc(var(--spacing) * 2);
    block-size: var(--control-h-lg);
    padding-inline: calc(var(--padding-x) * 1.25);
  }

  @media (hover: hover) {
    :where([data-control-family="sidebar"][data-slot="menu-button"]:hover),
    :where([data-control-family="sidebar"][data-slot="menu-action"]:hover) {
      background-color: var(--cui-sidebar-menu-button-hover-background);
      color: var(--cui-sidebar-menu-button-hover-foreground);
      box-shadow: var(--cui-sidebar-menu-button-hover-shadow);
    }

    :where([data-control-family="sidebar"][data-slot="menu-button"][data-state="open"]:hover) {
      background-color: var(--cui-sidebar-menu-button-active-background);
      color: var(--cui-sidebar-menu-button-active-foreground);
    }
  }

  :where([data-control-family="sidebar"][data-slot="menu-action"]:is(:active, [data-popup-open])),
  :where([data-control-family="sidebar"][data-slot="menu-button"]:active),
  :where([data-control-family="sidebar"][data-slot="menu-button"][data-active]) {
    background-color: var(--cui-sidebar-menu-button-active-background);
    color: var(--cui-sidebar-menu-button-active-foreground);
    box-shadow: var(--cui-sidebar-menu-button-active-shadow);
  }

  :where([data-control-family="sidebar"][data-slot="menu-button"][data-active]) {
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="sidebar"][data-slot="menu-button"][data-variant="outline"]) {
    background-color: var(--background);
    box-shadow: 0 0 0 1px var(--sidebar-border);
  }

  @media (hover: hover) {
    :where([data-control-family="sidebar"][data-slot="menu-button"][data-variant="outline"]:hover) {
      box-shadow: 0 0 0 1px oklch(from var(--foreground) l c h / 0.08);
    }
  }

  :where(
    [data-control-family="sidebar"][data-indicator="slide"]
      [data-control-family="sidebar"][data-slot="menu-button"]:is(:hover, :active, [data-active], [data-popup-open])
  ) {
    background-color: transparent;
  }

  @media (hover: hover) {
    :where([data-control-family="sidebar"][data-indicator="hover"] [data-slot="menu-button"]:hover:not([data-active])) {
      background-color: transparent;
      box-shadow: none;
    }
  }

  :where([data-control-family="sidebar"][data-slot="menu-action"]:is(:disabled, [aria-disabled="true"])),
  :where([data-control-family="sidebar"][data-slot="menu-button"]:disabled),
  :where([data-control-family="sidebar"][data-slot="menu-button"][aria-disabled="true"]) {
    opacity: 0.5;
  }

  :where([data-control-family="sidebar"][data-slot="group-content"]) {
    font-size: var(--text-body);
  }

  :where([data-control-family="sidebar"][data-slot="menu-action"]) {
    inset-block-start: calc(var(--control-h-md) / 2);
    padding: 0;
  }

  :where([data-control-family="sidebar"][data-slot="menu-button"][data-size="sm"] ~ [data-slot="menu-action"]) {
    inset-block-start: calc(var(--control-h-sm) / 2);
  }

  :where([data-control-family="sidebar"][data-slot="menu-button"][data-size="lg"] ~ [data-slot="menu-action"]) {
    inset-block-start: calc(var(--control-h-lg) / 2);
  }

  :where([data-control-family="sidebar"][data-slot="menu-button"]:has(~ [data-slot="menu-action"])) {
    padding-inline-end: calc(var(--spacing) * 8);
  }

  :where([data-control-family="sidebar"][data-slot="menu-action"]:focus-visible) {
    outline: 2px solid var(--sidebar-ring);
    outline-offset: 2px;
  }

  @media (hover: hover) and (pointer: fine) {
    :where([data-control-family="sidebar"][data-slot="menu-action"][data-show-on-hover]) {
      opacity: 0;
    }

    :where([data-control-family="sidebar"][data-slot="menu-item"]:is(:hover, :focus-within) [data-slot="menu-action"]),
    :where([data-control-family="sidebar"][data-slot="menu-action"][data-popup-open]) {
      opacity: 1;
    }
  }

  @media (pointer: coarse) {
    :where([data-control-family="sidebar"][data-slot="menu-action"]) {
      min-inline-size: 44px;
      min-block-size: 44px;
      inset-inline-end: 0;
      inset-block-start: max(22px, calc(var(--control-h-md) / 2));
    }

    :where([data-control-family="sidebar"][data-slot="menu-button"][data-size="sm"] ~ [data-slot="menu-action"]) {
      inset-block-start: max(22px, calc(var(--control-h-sm) / 2));
    }

    :where([data-control-family="sidebar"][data-slot="menu-button"][data-size="lg"] ~ [data-slot="menu-action"]) {
      inset-block-start: max(22px, calc(var(--control-h-lg) / 2));
    }

    :where([data-control-family="sidebar"][data-slot="menu-button"]:has(~ [data-slot="menu-action"])) {
      padding-inline-end: calc(var(--spacing) * 12);
    }
  }
}

@layer components {
  :where([data-control-family="sidebar"][data-slot="wrapper"]) {
    --cui-sidebar-wrapper-background: transparent;
    --cui-sidebar-wrapper-background-image: none;
    --cui-sidebar-inset-background: var(--background);
    --cui-sidebar-inset-background-image: none;
    --cui-sidebar-inset-shadow: var(--shadow-sm);
    background-color: var(--cui-sidebar-wrapper-background);
    background-image: var(--cui-sidebar-wrapper-background-image);
  }

  :where([data-control-family="sidebar"][data-slot="wrapper"]:has([data-control-family="sidebar"][data-variant="inset"])) {
    --cui-sidebar-wrapper-background: var(--sidebar);
  }

  :where([data-control-family="sidebar"][data-slot="root"]) {
    --cui-sidebar-inner-background: var(--sidebar);
    --cui-sidebar-inner-background-image: none;
    --cui-sidebar-inner-backdrop-filter: none;
    --cui-sidebar-inner-border-color: var(--sidebar-border);
    --cui-sidebar-inner-border-width: 0px;
    --cui-sidebar-inner-radius: 0px;
    --cui-sidebar-inner-shadow: none;
    --cui-sidebar-rail-divider-background: transparent;
    --cui-sidebar-group-label-foreground: oklch(from var(--sidebar-foreground) l c h / 0.7);
    --cui-sidebar-menu-button-radius: var(--radius-popup-item);
    --cui-sidebar-menu-button-foreground: var(--sidebar-foreground);
    --cui-sidebar-menu-button-hover-background: var(--hover-fill);
    --cui-sidebar-menu-button-hover-foreground: var(--foreground);
    --cui-sidebar-menu-button-hover-shadow: 0 0 transparent;
    --cui-sidebar-menu-button-active-background: var(--active-fill);
    --cui-sidebar-menu-button-active-shadow: 0 0 transparent;
    --cui-sidebar-menu-button-active-foreground: var(--foreground);
    background-color: var(--sidebar);
    color: var(--sidebar-foreground);
  }

  :where([data-control-family="sidebar"][data-slot="gap"]) {
    background-color: transparent;
    transition: width var(--duration-base) var(--ease-standard);
  }

  :where([data-control-family="sidebar"][data-slot="container"]) {
    transition-property: inset-inline-start, inset-inline-end, width;
    transition-duration: var(--duration-base);
    transition-timing-function: var(--ease-standard);
  }

  :where([data-control-family="sidebar"][data-slot="root"][data-variant="sidebar"][data-side="left"] [data-slot="container"]) {
    border-inline-end: 1px solid var(--sidebar-border);
  }

  :where([data-control-family="sidebar"][data-slot="root"][data-variant="sidebar"][data-side="right"] [data-slot="container"]) {
    border-inline-start: 1px solid var(--sidebar-border);
  }

  :where([data-control-family="sidebar"][data-slot="inner"]) {
    position: relative;
    isolation: isolate;
    border: var(--cui-sidebar-inner-border-width) solid var(--cui-sidebar-inner-border-color);
    border-radius: var(--cui-sidebar-inner-radius);
    box-shadow: var(--cui-sidebar-inner-shadow);
  }

  :where([data-control-family="sidebar"][data-slot="inner"])::before {
    content: "";
    position: absolute;
    inset: 0;
    z-index: -1;
    pointer-events: none;
    border-radius: inherit;
    corner-shape: inherit;
    background-color: var(--cui-sidebar-inner-background);
    background-image: var(--cui-sidebar-inner-background-image);
    -webkit-backdrop-filter: var(--cui-sidebar-inner-backdrop-filter);
    backdrop-filter: var(--cui-sidebar-inner-backdrop-filter);
  }

  :where([data-control-family="sidebar"][data-slot="root"][data-variant="floating"]) {
    --cui-sidebar-inner-border-width: 1px;
    --cui-sidebar-inner-radius: var(--radius-panel);
    --cui-sidebar-inner-shadow: var(--shadow-md);
  }

  :where([data-control-family="sidebar"][data-slot="rail"]) {
    inline-size: calc(var(--spacing) * 4);
    background-image: linear-gradient(var(--cui-sidebar-rail-divider-background), var(--cui-sidebar-rail-divider-background));
    background-position: center;
    background-repeat: no-repeat;
    background-size: 2px 100%;
    transition-property: --cui-sidebar-rail-divider-background, background-color, translate;
    transition-duration: var(--duration-base);
    transition-timing-function: var(--ease-standard);
  }

  :where([data-control-family="sidebar"][data-collapsible="offcanvas"] [data-slot="rail"]) {
    background-position: right;
  }

  @media (hover: hover) {
    :where([data-control-family="sidebar"][data-slot="rail"]:hover) {
      --cui-sidebar-rail-divider-background: var(--sidebar-border);
    }

    :where([data-control-family="sidebar"][data-collapsible="offcanvas"] [data-slot="rail"]:not([data-resizable]):hover) {
      background-color: var(--sidebar);
    }
  }

  :where(
    [data-control-family="sidebar"][data-slot="wrapper"][data-resizing="true"]
      [data-control-family="sidebar"]:is([data-slot="gap"], [data-slot="container"])
  ) {
    transition: none;
  }

  :where([data-control-family="sidebar"][data-slot="rail"][data-resizable]) {
    inline-size: calc(var(--spacing) * 2);
    background: none;
  }

  :where([data-control-family="sidebar"][data-slot="rail"][data-resizable])::after {
    content: "";
    position: absolute;
    inset-block: 12.5%;
    inset-inline-start: 50%;
    inline-size: 1px;
    background-image: linear-gradient(transparent, var(--cui-sidebar-rail-divider-background), transparent);
  }

  :where([data-control-family="sidebar"][data-slot="rail"]:is(:focus-visible, [data-resizing="true"])) {
    --cui-sidebar-rail-divider-background: var(--ring);
    outline: none;
  }

  :where([data-control-family="sidebar"][data-slot="inset"]) {
    background-color: var(--cui-sidebar-inset-background);
    background-image: var(--cui-sidebar-inset-background-image);
    transition-property: margin, border-radius, box-shadow;
    transition-duration: var(--duration-base);
    transition-timing-function: var(--ease-standard);
  }

  @media (width >= 64rem) {
    :where([data-control-family="sidebar"][data-slot="root"][data-variant="inset"] ~ [data-control-family="sidebar"][data-slot="inset"]) {
      margin: calc(var(--spacing) * 2);
      margin-inline-start: 0;
      border-radius: var(--radius-xl);
      box-shadow: var(--cui-sidebar-inset-shadow);
    }

    :where(
        [data-control-family="sidebar"][data-slot="root"][data-variant="inset"][data-state="collapsed"]
          ~ [data-control-family="sidebar"][data-slot="inset"]
      ) {
      margin-inline-start: calc(var(--spacing) * 2);
    }
  }

  :where([data-control-family="sidebar"][data-slot="header"]),
  :where([data-control-family="sidebar"][data-slot="footer"]) {
    gap: calc(var(--spacing) * 2);
    padding: calc(var(--spacing) * 2);
  }

  :where([data-control-family="sidebar"][data-slot="content-stack"]) {
    gap: calc(var(--spacing) * 2);
  }

  :where([data-control-family="sidebar"][data-slot="group"]) {
    padding: calc(var(--spacing) * 2);
  }

  :where([data-control-family="sidebar"][data-slot="menu"]) {
    gap: calc(var(--spacing) * 1);
  }

  :where([data-control-family="sidebar"][data-slot="menu"][data-submenu]) {
    margin-block: calc(var(--spacing) * 1);
    margin-inline-start: calc(var(--spacing) * 3);
    padding-inline-start: calc(var(--spacing) * 2);
    border-inline-start: 1px solid var(--sidebar-border);
    width: auto;
  }

  :where([data-control-family="sidebar"]:is([data-slot="group-label"], [data-slot="menu-button"])[aria-expanded] > [data-slot="chevron"]) {
    margin-inline-start: auto;
    transition: rotate var(--duration-base) var(--ease-standard);
  }

  :where([data-control-family="sidebar"][aria-expanded="true"] > [data-slot="chevron"]) {
    rotate: 90deg;
  }

  :where([data-control-family="sidebar"][data-slot="group-label"][aria-expanded]) {
    cursor: pointer;
    width: 100%;
    text-align: start;
  }

  @media (pointer: coarse) {
    :where([data-control-family="sidebar"]:is([data-slot="menu-button"], [data-slot="group-label"][aria-expanded])) {
      min-block-size: 44px;
    }

    :where([data-control-family="button"][data-sidebar-trigger]) {
      min-inline-size: 44px;
      min-block-size: 44px;
    }
  }

  :where([data-control-family="sidebar"][data-slot="menu"]:is([data-indicator="hover"], [data-indicator="slide"])) {
    gap: 0;
  }

  :where([data-control-family="sidebar"][data-slot="menu-track"] > [data-control-family="track-highlight"]) {
    --cui-track-highlight-radius: var(--cui-sidebar-menu-button-radius);
  }

  :where([data-control-family="sidebar"][data-slot="root"][data-side="right"] [data-control-family="sidebar"][data-slot="gap"]) {
    rotate: 180deg;
  }
}

