  railContainerRef,
  ...props
}: SidebarProps & { railContainerRef: Ref<HTMLDivElement> }) {
  const { side, collapsible } = useSidebarSurface();
  const { offcanvasRef } = useSidebarElements();
  const skin = useSkin();
  const { isMobile, state, openMobile, setOpenMobile } = useSidebar();
